		'The type “%1$s” is already declared in %2$s.' => 'Der Typ „%1$s“ ist bereits in %2$s deklariert.',
		'The name “%1$s” is already declared in %2$s.' => 'Der Name „%1$s“ ist bereits in %2$s deklariert.',
		'The field “%1$s” has wpml “%2$s” here and “%4$s” in %3$s: WPML keeps one mode per meta key.' => 'Das Feld „%1$s“ hat hier wpml „%2$s“ und in %3$s „%4$s“: WPML speichert einen Modus pro Meta-Schlüssel.',
